/* GENERATED by astro.config.mjs (launch-gate) from `launch` in src/data/store.ts at every build. Don't edit: change store.ts.
   The launch lock: until OPENS nobody gets these checkout links (they aren't in the pages either).
   GET /plugins/api/launch -> { open, now, opens, links }   links only from OPENS on.
   `now` is the server's clock, so a visitor's wrong or changed computer clock changes nothing (public/launch.js). */
const OPENS = 1795795200000; // 2026-11-27T16:00:00.000Z = 2026-11-27T17:00:00+01:00
const LINKS = {"tj-quick-paste-pro":"https://tonyjedits.gumroad.com/l/tjquickpaste?wanted=true","tj-quick-paste-light":"https://tonyjedits.gumroad.com/l/tjquickpastelight?wanted=true"};
const KEYS = ["tj-quick-paste-pro","tj-quick-paste-light"]; // checked by tools/to-portfolio.mjs: each needs a real link

// no rate limit: it's a tiny read-only answer, everyone asks at the same second at the launch, and the cheaper
// Netlify plans only allow two rate-limit rules per site (the vote and visit functions use them)
export const config = { path: '/plugins/api/launch' };

export default async () => {
  const now = Date.now();
  const open = now >= OPENS;
  return new Response(JSON.stringify(open ? { open, now, opens: OPENS, links: LINKS } : { open, now, opens: OPENS }), {
    headers: { 'content-type': 'application/json', 'cache-control': 'no-store' },
  });
};
